  "score.notYetHelp": "ECCS ଆପଣଙ୍କ କିଚେନ୍ ଇନ୍ସପେକ୍ସନ୍ କଲା ପରେ କିମ୍ବା ଆପଣଙ୍କ ପ୍ରଥମ ଚେକଲିଷ୍ଟର ସମୟ ହେଲା ପରେ ଆପଣଙ୍କ ସ୍କୋର୍ ଦେଖାଯିବ।",
