  "score.provisionalHelp": "ECCS ଏଯାଏଁ ଏହି କିଚେନ୍ ଇନ୍ସପେକ୍ସନ୍ କରିନାହିଁ, ତେଣୁ ସ୍କୋର୍ କେବଳ ଆପଣଙ୍କ ଲାଇସେନ୍ସ ଓ ଚେକଲିଷ୍ଟରୁ ହିସାବ ହୋଇଛି। ଇନ୍ସପେକ୍ସନ୍ ପରେ 100 ରୁ 60 ମାର୍କ ତାହାର ହେବ।",
  "score.how": "ଆପଣଙ୍କ ଶେଷ ECCS ଇନ୍ସପେକ୍ସନ୍ ପାଇଁ 60 ମାର୍କ, ଲାଇସେନ୍ସ ପାଇଁ 10 ଓ ଆଜିର ଚେକଲିଷ୍ଟ ପାଇଁ 30 ମାର୍କ। ଗୋଟିଏ ଗୋଟିଏ ଚେକଲିଷ୍ଟ ସବମିଟ୍ ହେଲେ ଚେକଲିଷ୍ଟର ମାର୍କ ଦିନସାରା ବଦଳେ।",
