  "score.about.checklists": "ମାର୍କ ଆଜିର ସବୁ ଚେକଲିଷ୍ଟରେ ସମାନ ଭାବେ ବଣ୍ଟାଯାଏ। ଠିକ୍ ସମୟରେ ସବମିଟ୍ କଲେ: ପୂରା ମାର୍କ। ଡେରିରେ ସବମିଟ୍ କଲେ: ଅଧା। ସବମିଟ୍ ନକଲେ: କିଛି ନାହିଁ।",
