  "offline.visitNotOnPhone": "ସିଗନାଲ୍ ନାହିଁ, ଆଉ ଏହି ଭିଜିଟ୍ ଏଯାଏଁ ଏହି ଫୋନ୍‌ରେ ସେଭ୍ ହୋଇନାହିଁ। ସିଗନାଲ୍ ଥିବାବେଳେ ଏହାକୁ ଥରେ ଖୋଲନ୍ତୁ।",
  "offline.inspectionNotOnPhone": "ସିଗନାଲ୍ ନାହିଁ, ଆଉ ଏହି ଇନ୍ସପେକ୍ସନ୍ ଏଯାଏଁ ଏହି ଫୋନ୍‌ରେ ସେଭ୍ ହୋଇନାହିଁ। ସିଗନାଲ୍ ଥିବାବେଳେ ଏହାକୁ ଥରେ ଖୋଲନ୍ତୁ।",
  "offline.visitGone": "ଏହି ଭିଜିଟ୍ ଆଉ ଆପଣଙ୍କ ଲିଷ୍ଟରେ ନାହିଁ। ECCS ଏହାକୁ ଅନ୍ୟ କାହାକୁ ଦେଇଛି କିମ୍ବା ହଟାଇଦେଇଛି।",
  "offline.inspectionGone": "ଏହି ଇନ୍ସପେକ୍ସନ୍ ଆଉ ଆପଣଙ୍କ ଲିଷ୍ଟରେ ନାହିଁ। ECCS ଏହାକୁ ଅନ୍ୟ କାହାକୁ ଦେଇଛି କିମ୍ବା ହଟାଇଦେଇଛି।",
  "offline.listNotOnPhone": "ସିଗନାଲ୍ ନାହିଁ, ଆଉ ଏହି ଲିଷ୍ଟ ଏଯାଏଁ ଏହି ଫୋନ୍‌ରେ ସେଭ୍ ହୋଇନାହିଁ। ସିଗନାଲ୍ ଥିବାବେଳେ ଏହାକୁ ଥରେ ଖୋଲନ୍ତୁ।",
  "offline.finishWaiting": "ଏହି ଫୋନ୍‌ରେ ଶେଷ ହୋଇଛି, କିନ୍ତୁ ଏଯାଏଁ ପଠାଯାଇନାହିଁ। ସିଗନାଲ୍ ଫେରିଲେ ପଠାଯିବ।",
  "offline.scoreOnPhone": "ଏହି ସ୍କୋର୍ ଆପଣଙ୍କ ଉତ୍ତରରୁ ଏହି ଫୋନ୍‌ରେ ହିସାବ ହୋଇଛି। ପଠାଗଲା ପରେ ECCS ଏହାକୁ ଦେଖିବ।",
