  "offline.maxPhotos": "ଗୋଟିଏ ଭିଜିଟ୍‌ରେ ଅତି ବେଶୀରେ {count} ଟି ଫଟୋ ରହିପାରିବ। ଆଉ ଗୋଟିଏ ଯୋଡ଼ିବାକୁ ଗୋଟିଏ ହଟାନ୍ତୁ।",
  "offline.dueTooEarly": "ଠିକ୍ କରିବାର ତାରିଖ ଇନ୍ସପେକ୍ସନ୍ ଆଗରୁ ହୋଇପାରିବ ନାହିଁ।",
  "offline.nothingApplies": "ଅତି କମ୍‌ରେ ଗୋଟିଏ ଚେକ୍ ଆଉଟଲେଟ୍ ପାଇଁ ଲାଗୁ ହେବା ଦରକାର। N/A ଦିଆଯାଇଥିବା ଗୋଟିଏ ଉତ୍ତର ବଦଳାନ୍ତୁ।",
  "offline.thisVisit": "ଏହି ଭିଜିଟ୍",
  "offline.thisInspection": "ଏହି ଇନ୍ସପେକ୍ସନ୍",
  "offline.held.visit.cancelled": "ଆପଣଙ୍କ କାମ ପଠାଯିବା ଆଗରୁ ECCS ଏହି ଭିଜିଟ୍ ବାତିଲ୍ କରିଦେଲା, ତେଣୁ ତାହା ପଠାଯାଇନାହିଁ। ତାହା ଏବେ ବି ଏହି ଫୋନ୍‌ରେ ଅଛି। କିଛି ଡିଲିଟ୍ କରିବା ଆଗରୁ ECCS ଅଫିସ୍‌କୁ ଫୋନ୍ କରନ୍ତୁ। ଏହି ଫୋନ୍‌ରେ ରଖାଯାଇଛି: {count}",
  "offline.held.visit.gone": "ଏହି ଭିଜିଟ୍ ଆଉ ଆପଣଙ୍କର ନୁହେଁ: ଆପଣଙ୍କ କାମ ପଠାଯିବା ଆଗରୁ ଏହାକୁ ଅନ୍ୟ କାହାକୁ ଦିଆଗଲା କିମ୍ବା ହଟାଇଦିଆଗଲା। ଆପଣଙ୍କ କାମ ଏବେ ବି ଏହି ଫୋନ୍‌ରେ ଅଛି। ECCS ଅଫିସ୍‌କୁ ଫୋନ୍ କରନ୍ତୁ। ସେମାନେ ଭିଜିଟ୍ ଆପଣଙ୍କୁ ଫେରାଇଦେଲେ \"ପୁଣି ପଠାନ୍ତୁ\" ଟ୍ୟାପ୍ କରନ୍ତୁ। ଏହି ଫୋନ୍‌ରେ ରଖାଯାଇଛି: {count}",
  "offline.held.visit.finished": "ଏହି ଭିଜିଟ୍ ଆଗରୁ ଅନ୍ୟ ଫୋନ୍‌ରୁ କିମ୍ବା ଅଫିସ୍ ପକ୍ଷରୁ ଶେଷ ହୋଇସାରିଥିଲା, ତେଣୁ ଏହି ଫୋନ୍‌ର କାମ ଯୋଡ଼ା ହେଲା ନାହିଁ। ତାହା ଏବେ ବି ଏହି ଫୋନ୍‌ରେ ଅଛି। ଦରକାର ନଥିଲେ ଏହି ଫୋନ୍‌ରୁ ଡିଲିଟ୍ କରନ୍ତୁ। ଏହି ଫୋନ୍‌ରେ ରଖାଯାଇଛି: {count}",
  "offline.held.inspection.cancelled": "ଆପଣଙ୍କ ଉତ୍ତର ପଠାଯିବା ଆଗରୁ ECCS ଏହି ଇନ୍ସପେକ୍ସନ୍ ବାତିଲ୍ କରିଦେଲା, ତେଣୁ ସେଗୁଡ଼ିକ ପଠାଯାଇନାହିଁ। ସେଗୁଡ଼ିକ ଏବେ ବି ଏହି ଫୋନ୍‌ରେ ଅଛି। କିଛି ଡିଲିଟ୍ କରିବା ଆଗରୁ ECCS ଅଫିସ୍‌କୁ ଫୋନ୍ କରନ୍ତୁ। ଏହି ଫୋନ୍‌ରେ ରଖାଯାଇଛି: {count}",
  "offline.held.inspection.gone": "ଏହି ଇନ୍ସପେକ୍ସନ୍ ଆଉ ଆପଣଙ୍କର ନୁହେଁ: ଆପଣଙ୍କ ଉତ୍ତର ପଠାଯିବା ଆଗରୁ ଏହାକୁ ଅନ୍ୟ କାହାକୁ ଦିଆଗଲା କିମ୍ବା ହଟାଇଦିଆଗଲା। ଆପଣଙ୍କ ଉତ୍ତର ଏବେ ବି ଏହି ଫୋନ୍‌ରେ ଅଛି। ECCS ଅଫିସ୍‌କୁ ଫୋନ୍ କରନ୍ତୁ। ସେମାନେ ଇନ୍ସପେକ୍ସନ୍ ଆପଣଙ୍କୁ ଫେରାଇଦେଲେ \"ପୁଣି ପଠାନ୍ତୁ\" ଟ୍ୟାପ୍ କରନ୍ତୁ। ଏହି ଫୋନ୍‌ରେ ରଖାଯାଇଛି: {count}",
  "offline.held.inspection.finished": "ଏହି ଇନ୍ସପେକ୍ସନ୍ ଆଗରୁ ଅନ୍ୟ ଫୋନ୍‌ରୁ କିମ୍ବା ଅଫିସ୍ ପକ୍ଷରୁ ଶେଷ ହୋଇସାରିଥିଲା, ତେଣୁ ଏହି ଫୋନ୍‌ର ଉତ୍ତର ଯୋଡ଼ା ହେଲା ନାହିଁ। ସେଗୁଡ଼ିକ ଏବେ ବି ଏହି ଫୋନ୍‌ରେ ଅଛି। ଦରକାର ନଥିଲେ ଏହି ଫୋନ୍‌ରୁ ଡିଲିଟ୍ କରନ୍ତୁ। ଏହି ଫୋନ୍‌ରେ ରଖାଯାଇଛି: {count}",
  "offline.heldTitle": "ପଠାଯାଇନାହିଁ",
