  "offline.deleteConfirm": "ପଠାଯାଇନଥିବା ଏହି କାମ ଏହି ଫୋନ୍‌ରୁ ଡିଲିଟ୍ କରିବେ? ଏହା ECCS କୁ କେବେ ପଠାଯାଇନାହିଁ ଓ ଆଉ ଫେରାଇ ହେବ ନାହିଁ। ଯାହା ହଜିଯିବ: {count}",
