  "offline.heldLine": "କିଛି କାମ ଗ୍ରହଣ ହେଲା ନାହିଁ ଓ ପଠାଯାଇନାହିଁ। ତାହା ଏହି ଫୋନ୍‌ରେ ରଖାଯାଇଛି। କ'ଣ କରିବେ ଦେଖିବାକୁ ଏହାକୁ ଖୋଲନ୍ତୁ। ରଖାଯାଇଛି: {count}",
  "offline.heldMark": "ପଠାଯାଇନାହିଁ। ଏହି ଫୋନ୍‌ରେ ରଖାଯାଇଛି: {count}",
