  "offline.stepsRejected": "ସର୍ଭର {title} ପାଇଁ ଆପଣ ଭରିଥିବା କିଛି ବିବରଣୀ ନେଲା ନାହିଁ। ସେଭ୍ ହୋଇନାହିଁ: {count}। ଏହାକୁ ଖୋଲି ସେଗୁଡ଼ିକ ପୁଣି ଭରନ୍ତୁ।",
  "offline.finishRejected": "{title} ଶେଷ ହୋଇପାରିଲା ନାହିଁ: କିଛି ଏବେ ବି ବାକି ଅଛି। ଏହାକୁ ଖୋଲନ୍ତୁ, ସବୁ ହୋଇଛି କି ଦେଖନ୍ତୁ, ଆଉ ପୁଣି ଶେଷ କରନ୍ତୁ।",

