  "plan.cancelConfirm": "{plan} ପ୍ଲାନ୍ ବାତିଲ୍ କରିବେ?\n\nଆପଣଙ୍କ ଭିଜିଟ୍ {date} ଯାଏଁ ଚାଲିବ, ଯେଉଁ ଦିନ ଆଗରୁ ଇନଭଏସ୍ ହୋଇସାରିଥିବା ସାଇକଲ୍ ସରେ।\n\n{date} ପରେ ପ୍ଲାନ୍ ରିନ୍ୟୁ ହେବ ନାହିଁ, ଆଉ କୌଣସି ଇନଭଏସ୍ ହେବ ନାହିଁ, ଓ ସେହି ଦିନ ପରର ଭିଜିଟ୍ ଆପଣଙ୍କ କ୍ୟାଲେଣ୍ଡରରୁ ହଟାଇଦିଆଯିବ।\n\nଆପଣ {date} ଯାଏଁ ଏହା ଫେରାଇ ନେଇପାରିବେ।",
  "plan.cancelConfirmNow": "{plan} ପ୍ଲାନ୍ ବାତିଲ୍ କରିବେ?\n\nଏହା ଆଜି ହିଁ ସରିବ। ଏହାର ଯେଉଁ ଭିଜିଟ୍ ଆରମ୍ଭ ହୋଇନାହିଁ, ସେଗୁଡ଼ିକ ଆପଣଙ୍କ କ୍ୟାଲେଣ୍ଡରରୁ ହଟାଇଦିଆଯିବ ଓ ଆଉ କୌଣସି ଇନଭଏସ୍ ହେବ ନାହିଁ।\n\nଏହାକୁ ଆଉ ଫେରାଇ ହେବ ନାହିଁ, କିନ୍ତୁ ଆପଣ ପୁଣି ପ୍ଲାନ୍ ନେଇପାରିବେ।",
