  "push.channel.updates": "ଅପଡେଟ୍",
  "push.channel.updatesHelp": "ଭିଜିଟ୍, ରିପୋର୍ଟ, ଇସ୍ୟୁ ଓ ଲଗଇନ୍, ହେବା ମାତ୍ରେ",
  "push.channel.reminders": "ରିମାଇଣ୍ଡର୍",
  "push.channel.remindersHelp": "ସମୟ ପାର ହୋଇଥିବା ଚେକଲିଷ୍ଟ, ସରିବାକୁ ଥିବା ଲାଇସେନ୍ସ, ଆସୁଥିବା ଭିଜିଟ୍",
  "push.ask.title": "ସାଙ୍ଗେ ସାଙ୍ଗେ ଜାଣିବେ?",
  "push.ask.body": "ଯେତେବେଳେ କିଛି ଆପଣଙ୍କ ଧ୍ୟାନ ଦରକାର କରେ, ECCS ଏହି ଫୋନ୍‌ରେ ନୋଟିଫିକେସନ୍ ଦେଖାଇପାରିବ: ଭିଜିଟ୍ ଶେଷ ହୋଇଛି, ECCS ଉତ୍ତର ଦେଇଛି, ଚେକଲିଷ୍ଟର ସମୟ ପାର ହୋଇଛି, ଲାଇସେନ୍ସ ସରିବାକୁ ଯାଉଛି। ଦେଖିବା ପାଇଁ ଆପଣଙ୍କୁ ବାରମ୍ବାର ଆପ୍ ଖୋଲିବାକୁ ପଡ଼ିବ ନାହିଁ।",
  "push.ask.shared": "ଅନେକ ଲୋକ ବ୍ୟବହାର କରୁଥିବା ଫୋନ୍‌ରେ, ଯିଏ ଲଗଇନ୍ କରିଛନ୍ତି କେବଳ ସେ ଏଗୁଡ଼ିକ ପାଆନ୍ତି। ଲକ୍ କଲା ପରେ କିଛି ଦେଖାଯାଏ ନାହିଁ।",
  "push.ask.yes": "ନୋଟିଫିକେସନ୍ ଚାଲୁ କରନ୍ତୁ",
  "push.ask.notNow": "ଏବେ ନୁହେଁ",
  "push.status.on": "ଏହି ଫୋନ୍‌ରେ ନୋଟିଫିକେସନ୍ ଚାଲୁ ଅଛି।",
  "push.status.off": "ଏହି ଫୋନ୍‌ରେ ନୋଟିଫିକେସନ୍ ବନ୍ଦ ଅଛି। ନୂଆ ନୋଟିଫିକେସନ୍ କେବଳ ଆପ୍ ଖୋଲିଲେ ଦେଖାଯିବ।",
  "push.status.blocked": "ଏହି ଫୋନ୍‌ର ସେଟିଂସ୍‌ରେ ECCS ର ନୋଟିଫିକେସନ୍ ବ୍ଲକ୍ ହୋଇଛି। ସାଙ୍ଗେ ସାଙ୍ଗେ ଜାଣିବା ପାଇଁ ସେଠାରେ ଅନୁମତି ଦିଅନ୍ତୁ।",
  "push.status.failed": "ଏହି ଫୋନ୍‌ରେ ନୋଟିଫିକେସନ୍ ସେଟ୍ କରି ହେଲା ନାହିଁ। ଇଣ୍ଟରନେଟ୍ ସଂଯୋଗ ଦେଖି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
  "push.status.serverOff": "ଏହି ଫୋନ୍‌ରେ ନୋଟିଫିକେସନ୍ ଚାଲୁ ଅଛି, କିନ୍ତୁ ECCS ଏଯାଏଁ ଫୋନ୍‌କୁ ନୋଟିଫିକେସନ୍ ପଠାଉନାହିଁ।",
  "push.status.unavailable": "ଆପ୍‌ର ଏହି ଭର୍ସନ୍ ଫୋନ୍‌ରେ ନୋଟିଫିକେସନ୍ ଦେଖାଇପାରିବ ନାହିଁ। ନୂଆ ନୋଟିଫିକେସନ୍ ଆପ୍ ଖୋଲିଲେ ଦେଖାଯିବ।",
