  "public.how.2": "ପ୍ରତିଟି ବିଷୟ ପୂରଣ ହୋଇଛି କି ନାହିଁ ଲେଖାଯାଏ। ମିଳିପାରୁଥିବା ମୋଟ ମାର୍କରୁ ଯେତେ ମାର୍କ ମିଳିଛି, ତାହା 100 ରୁ ଏକ ସଂଖ୍ୟା ଭାବେ ସ୍କୋର୍। ଗୁରୁତର ବିପଦ ସମ୍ପର୍କିତ ବିଷୟର ମାର୍କ ଦୁଇଗୁଣ ଗଣାଯାଏ।",
  "public.how.3": "ଗ୍ରେଡ୍ A+ ମାନେ {aPlus} କିମ୍ବା ଅଧିକ, A ମାନେ {a} କିମ୍ବା ଅଧିକ, B ମାନେ {b} କିମ୍ବା ଅଧିକ। {b} ରୁ କମ୍ ହେଲେ, କିମ୍ବା ଗୁରୁତର ବିପଦର କୌଣସି ବିଷୟ ପୂରଣ ନ ହେଲେ, କୌଣସି ଗ୍ରେଡ୍ ଦିଆଯାଏ ନାହିଁ।",
  "public.how.4": "ପ୍ରତିଟି ରିପୋର୍ଟ ଏଠାରେ ଦେଖାଯିବା ଆଗରୁ ECCS ଅଫିସ୍ ତାହାକୁ ମଞ୍ଜୁର କରେ। ଏକ ଫଳ {days} ଦିନ ଦେଖାଯାଏ ଓ ତା'ପରେ ପରବର୍ତ୍ତୀ ଇନ୍ସପେକ୍ସନ୍ ପର୍ଯ୍ୟନ୍ତ ଏହି ପେଜ୍‌ରୁ ହଟାଇ ଦିଆଯାଏ।",
  "public.not.heading": "ଏଥିରେ କ'ଣ ନାହିଁ",
  "public.not.2": "ଖାଦ୍ୟର ସ୍ୱାଦ କିମ୍ବା ମାନ, ସର୍ଭିସ୍ କିମ୍ବା ଖାଇବା ଜାଗା ବିଷୟରେ ଏହା କିଛି କହେ ନାହିଁ।",
  "public.not.3": "ଖାଦ୍ୟ ଆପଣଙ୍କ ପାଇଁ ନିରାପଦ ବୋଲି ଏହା କୌଣସି ନିଶ୍ଚୟତା ନୁହେଁ। ଆପଣଙ୍କର ଆଲର୍ଜି ଥିଲେ ଷ୍ଟାଫ୍‌କୁ ପଚାରନ୍ତୁ।",
  "public.gov.heading": "ସରକାରୀ ରେଟିଂ ନୁହେଁ",
  "public.gov.check": "ପ୍ରତିଟି ରେଷ୍ଟୁରାଣ୍ଟକୁ ନିଜର FSSAI ଲାଇସେନ୍ସ ସବୁରି ଆଖିରେ ପଡ଼ିବା ଭଳି ରଖିବାକୁ ପଡ଼େ। ଆପଣ FSSAI ର ନିଜ ୱେବସାଇଟ୍ (foscos.fssai.gov.in) କିମ୍ବା ତାହାର Food Safety Connect ଆପ୍‌ରେ ଲାଇସେନ୍ସ ଯାଞ୍ଚ କରିପାରିବେ କିମ୍ବା ଅଭିଯୋଗ କରିପାରିବେ।",
