  "face.consent.intro": "ଏହା ନିଜେ ପଢ଼ନ୍ତୁ, କିମ୍ବା କାହାକୁ ପଢ଼ି ଶୁଣାଇବାକୁ କୁହନ୍ତୁ। ବାଛିବା ଆପଣଙ୍କ ହାତରେ।",
  "face.consent.who": "{employer} ଆପଣଙ୍କ ନିଯୁକ୍ତିଦାତା (ଯିଏ ଆପଣଙ୍କୁ କାମରେ ରଖିଛନ୍ତି) ଓ ସେ ଏହା ମାଗୁଛନ୍ତି। ଏହି ଆପ୍ ଚଳାଉଥିବା କମ୍ପାନୀ ECCS, {employer} ପାଇଁ ଏହି ଡାଟା ରଖେ।",
  "face.consent.why": "ଏହା କେବଳ ଗୋଟିଏ କାମରେ ବ୍ୟବହାର ହୁଏ: ଆସିବା ଓ ଯିବା ହାଜିରା ବେଳେ ଏ ଆପଣ ବୋଲି ଜାଣିବା ପାଇଁ। ସେହି ସମୟଗୁଡ଼ିକରୁ ଆପଣଙ୍କ ଦରମାର ହିସାବ ହୁଏ।",
  "face.consent.not": "ଏହା ଆଉ କୌଣସି କାମରେ ବ୍ୟବହାର ହୁଏ ନାହିଁ। ଏହା ବିକ୍ରି ହୁଏ ନାହିଁ, ଆଉ କାହାକୁ ଦିଆଯାଏ ନାହିଁ, ଓ ବିଜ୍ଞାପନ ପାଇଁ ବ୍ୟବହାର ହୁଏ ନାହିଁ।",
  "face.consent.choice": "ଆପଣ ନା କହିପାରିବେ। ଆପଣଙ୍କ କାମ କିମ୍ବା ଦରମାରେ କିଛି ବଦଳେ ନାହିଁ। ତା' ବଦଳରେ ମାଲିକ କିମ୍ବା ମ୍ୟାନେଜର ଆପଣଙ୍କ ଆସିବା ଓ ଯିବା ହାଜିରା କରିବେ।",
  "face.consent.withdraw": "ଆପଣ ଯେକୌଣସି ସମୟରେ ନିଜ ମତ ବଦଳାଇପାରିବେ: ମାଲିକଙ୍କୁ କୁହନ୍ତୁ, ଆଉ ଆପଣଙ୍କ ମୁହଁର ନମୁନା ସଙ୍ଗେ ସଙ୍ଗେ ଡିଲିଟ୍ ହୁଏ। ଆପଣ ଏହି କାମ ଛାଡ଼ିଲେ ବି ଏହା ଡିଲିଟ୍ ହୁଏ।",
  "face.consent.ask": "ଆପଣଙ୍କର କିଛି ପ୍ରଶ୍ନ ଥିଲେ, ମାଲିକଙ୍କୁ ପଚାରନ୍ତୁ।",
  "face.consent.under18": "ଆପଣଙ୍କ ବୟସ 18 ବର୍ଷରୁ କମ୍ ହେଲେ, \"ମୁଁ ରାଜି ନୁହେଁ\" ବାଛନ୍ତୁ।",
  "face.consent.agree": "ମୁଁ ରାଜି",
