  "public.disclaimer.own": "ଏହି ପେଜ୍‌ରେ ଥିବା କିଛି ବି ସରକାରୀ ରେଟିଂ, ସରକାରୀ ଲାଇସେନ୍ସ, ସରକାରୀ ଇନ୍ସପେକ୍ସନ୍ କିମ୍ବା ସରକାରୀ ସାର୍ଟିଫିକେଟ୍ ନୁହେଁ। ଏହି ପେଜ୍‌ରେ ଥିବା ସ୍କୋର୍ ଓ ଯେକୌଣସି ଇନ୍ସପେକ୍ସନ୍ ଫଳ ECCS ର ନିଜର।",
