  "public.photos.by.RESTAURANT": "ଦୈନିକ ଚେକ୍ ସମୟରେ ରେଷ୍ଟୁରାଣ୍ଟର ଷ୍ଟାଫ୍ ଉଠାଇଛନ୍ତି",
