  "public.about.heading": "ଏହି ପେଜ୍ ବିଷୟରେ",
  "public.about.notRating": "ECCS ହାଇଜିନ୍ ସ୍କୋର୍ FSSAI ହାଇଜିନ୍ ରେଟିଂ ନୁହେଁ।",
  "public.about.score": "ସ୍କୋର୍‌ର ତିନୋଟି ଅଂଶ ଅଛି। ECCS ର ଶେଷ ଇନ୍ସପେକ୍ସନ୍ ପାଇଁ ଅତି ବେଶିରେ {inspection} ମାର୍କ, ଯଦି ତାହା ଗତ {days} ଦିନ ଭିତରେ ହୋଇଥାଏ। ରେଷ୍ଟୁରାଣ୍ଟର ଲାଇସେନ୍ସ ପାଇଁ ଅତି ବେଶିରେ {licences} ମାର୍କ, ଯେବେ ସେଗୁଡ଼ିକ ସରିନଥାଏ ଓ ସେଗୁଡ଼ିକର କପି ECCS ପାଖରେ ଥାଏ। ସେହି ଦିନର ଚେକଲିଷ୍ଟ ପାଇଁ ଅତି ବେଶିରେ {checklists} ମାର୍କ, ଯେବେ ସେଗୁଡ଼ିକ ସବମିଟ୍ ହୁଏ, ଓ ଠିକ୍ ସମୟରେ ହୁଏ। ଲାଇସେନ୍ସ ଓ ଦୈନିକ ଚେକ୍ ରେଷ୍ଟୁରାଣ୍ଟ ନିଜେ ଯେମିତି ରେକର୍ଡ କରିଛି ସେମିତି ଅଛି। ECCS ଲାଇସେନ୍ସକୁ କର୍ତ୍ତୃପକ୍ଷଙ୍କ ପାଖରେ ଯାଞ୍ଚ କରେ ନାହିଁ।",
