  "public.poster.what": "ଗତକାଲିର ହାଇଜିନ୍ ସ୍କୋର୍, ଆମର ଦୈନିକ ଚେକଲିଷ୍ଟ ଓ ଆମ କିଚେନ୍‌ର ଫଟୋ।",
  "cpage.inspection.NONE": "ଏଯାଏଁ କୌଣସି ମଞ୍ଜୁର ହୋଇଥିବା ECCS ଇନ୍ସପେକ୍ସନ୍ ନାହିଁ। ଆପଣଙ୍କ ପେଜ୍ ତାହା ବିନା ଦେଖାଯାଏ, ଓ ସ୍କୋର୍ ପାଖରେ ସେ କଥା ଲେଖା ଥାଏ।",
