  "cpage.inspection.EXPIRED": "ECCS ର ଶେଷ ଇନ୍ସପେକ୍ସନ୍ ({date}) {days} ଦିନରୁ ଅଧିକ ପୁରୁଣା, ତେଣୁ ତାହା ଆଉ ଆପଣଙ୍କ ପେଜ୍‌ରେ ନାହିଁ। ଆପଣଙ୍କ ପେଜ୍‌ର ବାକି ଅଂଶ ଏବେ ବି ଦେଖାଯାଉଛି।",
