  "cpage.switch.item8": "ଆପଣଙ୍କ ଦୈନିକ ଚେକଲିଷ୍ଟର ନାମ, ପ୍ରତିଟିରେ କେତୋଟି ଚେକ୍ ଅଛି, ଓ ଗତକାଲି ପ୍ରତିଟି ହୋଇଥିଲା କି ନାହିଁ: ଠିକ୍ ସମୟରେ, ଡେରିରେ କିମ୍ବା ହୋଇନାହିଁ",
