  "cpage.photos.add": "ଆପଣଙ୍କ ଦୈନିକ ଚେକ୍‌ରୁ ଫଟୋ ଯୋଡ଼ନ୍ତୁ",
  "cpage.photos.addHint": "ଗତ {days} ଦିନର। ECCS ପ୍ରଥମେ ପ୍ରତିଟି ଫଟୋ ଦେଖେ।",
  "cpage.checks.title": "ଆପଣଙ୍କ ଦୈନିକ ଚେକ୍‌ର ଫଟୋ",
  "cpage.checks.help": "ସଫା ଯନ୍ତ୍ରପାତି ଓ ସଫା ଜାଗା ଦେଖାଉଥିବା ଫଟୋ ବାଛନ୍ତୁ। ECCS ନ ଦେଖିବା ପର୍ଯ୍ୟନ୍ତ ଆପଣଙ୍କ ପେଜ୍‌ରେ କିଛି ଦେଖାଯାଏ ନାହିଁ।",
  "cpage.checks.which": "ଏଗୁଡ଼ିକ \"ଠିକ୍ ଅଛି\" ମାର୍କ ହୋଇଥିବା ଚେକ୍‌ର ଫଟୋ, ଗତ {days} ଦିନ ଭିତରେ ସବମିଟ୍ ହୋଇଥିବା ଚେକଲିଷ୍ଟରୁ।",
  "cpage.checks.reviewMore": "ECCS କେବଳ ଆପଣ ଏଠାରୁ ପଠାଉଥିବା ଫଟୋ ଦେଖେ, ଆପଣଙ୍କ ଚେକଲିଷ୍ଟର ଆଉ କିଛି ଦେଖେ ନାହିଁ।",
  "cpage.checks.review": "ଆପଣଙ୍କ ପେଜ୍‌ରେ ଦେଖାଯିବା ଆଗରୁ ECCS ଏହି ଫଟୋ ଦେଖିବ।",
  "cpage.checks.none": "ବାଛିବାକୁ କୌଣସି ଫଟୋ ନାହିଁ। \"ଠିକ୍ ଅଛି\" ମାର୍କ ହୋଇଥିବା ଚେକ୍‌ର ଫଟୋ ସହ ଚେକଲିଷ୍ଟ ସବମିଟ୍ ହେଲା ପରେ ସେଗୁଡ଼ିକ ଏଠାରେ ଦେଖାଯାଏ।",
