  "vendors.none": "କୌଣସି ସପ୍ଲାୟର ମିଳିଲେ ନାହିଁ। ଅନ୍ୟ ଶବ୍ଦ ଦେଇ ଦେଖନ୍ତୁ କିମ୍ବା \"ସବୁ\" ବାଛନ୍ତୁ।",
  "vendors.empty": "ଏଯାଏଁ ଲିଷ୍ଟରେ କୌଣସି ସପ୍ଲାୟର ନାହାନ୍ତି।",
  "vendors.about.title": "ଏହି ଲିଷ୍ଟ ବିଷୟରେ",
  "vendors.about.notChecked": "ECCS ଆପଣଙ୍କ ସୁବିଧା ପାଇଁ ଏହି ସପ୍ଲାୟରମାନଙ୍କୁ ଲିଷ୍ଟରେ ରଖିଛି। ECCS ସେମାନଙ୍କୁ ଯାଞ୍ଚ କରିନାହିଁ ଓ ସେମାନଙ୍କ ବିଷୟରେ କୌଣସି ନିଶ୍ଚୟତା ଦିଏ ନାହିଁ।",
  "vendors.about.fssai": "FSSAI କହେ ଯେ ରେଷ୍ଟୁରାଣ୍ଟ କେବଳ ଲାଇସେନ୍ସ କିମ୍ବା ରେଜିଷ୍ଟ୍ରେସନ୍ ଥିବା ସପ୍ଲାୟରଙ୍କଠାରୁ ଖାଦ୍ୟ ସାମଗ୍ରୀ କିଣିବ ଓ ତାହାର ରେକର୍ଡ ରଖିବ। କିଣିବା ଆଗରୁ FSSAI ର ୱେବସାଇଟ୍ foscos.fssai.gov.in ରେ ସପ୍ଲାୟରଙ୍କ ଲାଇସେନ୍ସ ଯାଞ୍ଚ କରନ୍ତୁ।",
  "vendors.sampleNumber": "ଏହା ଏକ ନମୁନା ସପ୍ଲାୟର, ତେଣୁ ନମ୍ବରଟି ଅସଲି ନୁହେଁ।",
