  "legal.accept.intro": "ଏହା ଆପଣ ଓ ECCS ମଧ୍ୟରେ ଆଇନଗତ ଭାବେ ବାଧ୍ୟକାରୀ ଏକ ଚୁକ୍ତି। ଡକ୍ୟୁମେଣ୍ଟଗୁଡ଼ିକ ପଢ଼ନ୍ତୁ, ତା'ପରେ ଆଗକୁ ବଢ଼ିବା ପାଇଁ ସହମତ ହୁଅନ୍ତୁ।",
  "legal.accept.introOwner": "ଏହା {restaurant} ଓ ECCS ମଧ୍ୟରେ ଆଇନଗତ ଭାବେ ବାଧ୍ୟକାରୀ ଏକ ଚୁକ୍ତି, ଯାହା ଆପଣ ନିଜ ରେଷ୍ଟୁରାଣ୍ଟ ପକ୍ଷରୁ କରୁଛନ୍ତି। ଡକ୍ୟୁମେଣ୍ଟଗୁଡ଼ିକ ପଢ଼ନ୍ତୁ, ତା'ପରେ ଆଗକୁ ବଢ଼ିବା ପାଇଁ ସହମତ ହୁଅନ୍ତୁ।",
